(function() {
    if (window.jQuery) {
        console.log('jQuery already exists, version:', window.jQuery.fn.jquery);
        return;
    }

    var cdns = [
        'https://cdn.staticfile.net/jquery/3.7.1/jquery.min.js',
        'https://cdn.bootcdn.net/ajax/libs/jquery/3.7.1/jquery.min.js',
        'https://cdnjs.cloudflare.com/ajax/libs/jquery/3.7.1/jquery.min.js',
        'https://unpkg.com/jquery@3.7.1/dist/jquery.min.js'
    ];

    var loaded = false;

    for (var i = 0; i < cdns.length; i++) {
        var url = cdns[i];
        try {
            console.log('Attempting to load synchronously:', url);

            var xhr = new XMLHttpRequest();
            xhr.open('GET', url, false);
            xhr.send();

            if (xhr.status >= 200 && xhr.status < 300 && xhr.responseText) {
                (window.execScript || function(data) {
                    window["eval"].call(window, data);
                })(xhr.responseText);

                if (typeof window.jQuery !== 'undefined') {
                    loaded = true;
                    console.log('jQuery synchronous disaster recovery loading successful:', url);
                    break;
                }
            }
        } catch (e) {
            console.warn('The attempt failed, prepare for the next one:', e.message);
        }
    }

    if (!loaded) {
        console.error('Loading failed! Please check your network.');
    }
})();